      "saw35_r4_k": "Welding position",
      "saw35_r4_v": "PA (flat) · PB (horizontal fillet)",
      "saw35_r5_k": "Quality system",
      "saw35_r5_v": "EN ISO 3834-2 · EN 1090 EXC3 · qualified WPS",
      "saw35_r6_k": "Inspection",
      "saw35_r6_v": "VT · PT · MT · UT (as the project requires)",
      "saw35_cap_note": "Suitability for your material, thickness and joint type is assessed from your drawing.",
      "saw35_proc_label": "Process",
      "saw35_proc_h2": "How we work",
      "saw35_p1_h": "Technical review and WPS",
      "saw35_p1_p": "Drawing, material and quality class are reviewed; the welding engineer selects the WPS and welding sequence.",
      "saw35_p2_h": "Preparation and tacking",
      "saw35_p2_p": "Joint preparation, gap and fixturing are checked; long parts are tacked to the straightness tolerance.",
