      "saw35_p3_p": "The seam is welded continuously on the 35 m line to the WPS parameters; current, voltage and speed are recorded.",
      "saw35_p4_h": "Inspection and documentation",
      "saw35_p4_p": "Visual inspection and required NDT are carried out; dimensional report, material certificates and weld records ship with the part.",
      "saw35_sec_label": "Industries",
      "saw35_sec_h2": "Who we weld for",
      "saw35_s1_t": "Construction machinery",
